# boxctl: timeout=60
echo "--- apt history"; tail -12 /var/log/apt/history.log 2>/dev/null | cut -c1-300; echo "--- unattended"; tail -6 /var/log/unattended-upgrades/unattended-upgrades.log 2>/dev/null | cut -c1-200; echo "--- journal 06:22-06:25"; sudo journalctl --since "2026-11-12 06:22:00" --until "2026-11-12 06:25:00" --no-pager 2>/dev/null | grep -i "needrestart\|restart\|apt\|unattended\|Stopping\|Started" | cut -c1-190 | head -24; echo "--- needrestart conf"; grep -rn "nrconf{restart}" /etc/needrestart/ 2>/dev/null | head -3; systemctl list-timers --no-pager 2>/dev/null | grep -i "apt\|unattended" | cut -c1-150
